class MedianFinder {
  constructor() {
    this.low = [];
    // max side (kept sorted ascending; max at end)
    this.high = [];
    // min side (kept sorted ascending; min at front)
  }
  addNum(x) {
    this.low.push(x);
    this.low.sort((a, b) => a - b);
    this.high.push(this.low.pop());
    this.high.sort((a, b) => a - b);
    if (this.high.length > this.low.length) this.low.push(this.high.shift());
  }
  findMedian() {
    if (this.low.length > this.high.length) return this.low[this.low.length - 1];
    return (this.low[this.low.length - 1] + this.high[0]) / 2;
  }
}

const mf = new MedianFinder();
[5, 15, 1, 3].forEach(x => mf.addNum(x));
console.log(mf.findMedian());

